pub type Time = { hours: Int; minutes: Int; }

impl Display for Time {
  fn fmt(self: &Time, f: &mut Formatter) -> Result[(), FmtError] {
    var h = self.hours.to_str();
    var m = self.minutes.to_str();
    if self.hours < 10 { h = "0" + h; }
    if self.minutes < 10 { m = "0" + m; }
    return f.write_str(h + ":" + m);
  }
}

fn main() -> Int {
  let t = Time{ hours: 9, minutes: 5 };
  let s = t.to_str();
  return s.len();
}
